@app.get("/invoices/<int:inv_id>")
@login_required
def get_invoice(inv_id):
    inv = Invoice.query.get_or_404(inv_id)
    if inv.owner_id != current_user.id:    # the missing line in IDOR bugs
        abort(404)                          # don't reveal existence
    return inv.to_json()

